export type MaterialLook = 'cube' | 'shaped' | 'ladder' | 'fluid' | 'cross';
export type RenderMode = 'opaque' | 'cutout' | 'translucent';

/** Texture tiles (dwell-mesh textures.rs) per face group; untextured materials use `color`. */
export interface MaterialTextures {
  top: string;
  side: string;
  bottom: string;
}

export interface BlockProperty {
  name: string;
  values: readonly string[];
}

/** A block: a namespaced id, its typed properties and the run of runtime state ids it owns. */
export interface BlockDef {
  id: string;
  first: number;
  count: number;
  properties: readonly BlockProperty[];
  /** Its sound set (shared/sounds, docs/AUDIO.md); none: the sounds' fallback set. */
  sound?: string;
}

/** One block state with how it is drawn (the physics side lives in the C++ core). */
export interface StateDef {
  /** Runtime state id. */
  id: number;
  /** Canonical string: `ns:name[k=v,…]`, every property, keys alphabetical. */
  state: string;
  block: number;
  values: Readonly<Record<string, string>>;
  look: MaterialLook;
  /** How its pixels are drawn (docs/TRANSPARENT_BLOCKS.md). */
  render: RenderMode;
  color: number;
  opacity: number;
  textures?: MaterialTextures;
  /** Ladders: the face whose side the plate faces (0 +X, 1 −X, 4 +Z, 5 −Z). */
  ladderFace?: number;
  /** The box it is aimed at by, when not the whole cell: min x, y, z, max x, y, z in the cell (0..1), turned to its facing. */
  selection?: readonly [number, number, number, number, number, number];
  /** Index into SHAPES: the solid's geometry in its cell (0 = none). */
  shape: number;
  /** Shaped blocks only: water fills the open part of the cell (SLOPE_BLOCKS.md §3.1). */
  flooded: boolean;
  /** In the infinite creative palette (§6.5; C++ `Placeable`). */
  placeable: boolean;
}

/** One polygon of a shape: convex, outward-wound, on cell face `tag` (0 +X, 1 −X, 2 +Y, 3 −Y, 4 +Z, 5 −Z) or the sloped surface (6). */
export interface ShapeFace {
  tag: number;
  pts: readonly (readonly [number, number, number])[];
}

/** Baked solid geometry of a voxel state inside its 1 m cell (shared/blocks/shapes.mjs). */
export interface ShapeDef {
  /** Top-surface corner heights in halves of a cell, NW NE SE SW. */
  corners: readonly [number, number, number, number];
  inverted: boolean;
  /** Top-surface diagonal: 0 NW–SE, 1 NE–SW. */
  diagonal: number;
  convex: boolean;
  volume: number;
  /** Side profile heights (halves) at the face's low end, middle and high end, faces +X −X +Z −Z. */
  sides: readonly (readonly [number, number, number])[];
  fullTop: boolean;
  fullBottom: boolean;
  minY: number;
  maxY: number;
  faces: readonly ShapeFace[];
}

